<script setup lang="ts">
import GenerationTaskProgress from './GenerationTaskProgress.vue'
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {generationEvolutionApi as api} from '../services/generationEvolutionApi'
import {useModelAccess} from '../composables/useModelAccess'
import {ApiError} from '../services/apiClient'
import type {Insight,LearningGuide} from '../types/generationEvolution'
const props=defineProps<{sessionId:string;revisionId:string}>(),emit=defineEmits<{file:[path:string]}>()
const ensureModel=useModelAccess(),insight=ref<Insight<LearningGuide>|null>(null),busy=ref(false),error=ref('')
let alive=true,timer:ReturnType<typeof setTimeout>|undefined,key=''
onMounted(()=>void refresh());onBeforeUnmount(()=>{alive=false;clearTimeout(timer)})
const message=(e:unknown)=>e instanceof ApiError?e.message:'导览暂时不可用，请重试'
async function refresh(attempt=0){clearTimeout(timer);try{const saved=await api.latestGuide(props.sessionId,props.revisionId);if(!alive)return;insight.value=saved;if(saved?.status==='RUNNING'&&attempt<300)timer=setTimeout(()=>void refresh(attempt+1),2000)}catch(e){if(alive)error.value=message(e)}}
async function generate(){if(busy.value||insight.value?.status==='RUNNING')return;busy.value=true;error.value='';try{if(!await ensureModel('生成项目学习导览'))return;if(!alive)return;if(!key)key=crypto.randomUUID();const value=await api.guide(props.sessionId,props.revisionId,key);if(!alive)return;insight.value=value;key='';await refresh()}catch(e){if(alive)error.value=message(e)}finally{if(alive)busy.value=false}}
</script>
<template><section class="learning"><h3>带我读懂这个项目</h3><p>先看做什么、有哪些模块，再沿业务流程读源码。导览只属于当前选用版本。</p><p v-if="error" class="notice error" role="alert">{{error}}</p><button class="button secondary" :disabled="busy||insight?.status==='RUNNING'" @click="generate">{{insight?.status==='RUNNING'?'AI 正在整理导览…':insight?.content?'更新此版本导览 · 使用 API 额度':'生成此版本导览 · 使用 API 额度'}}</button><button v-if="insight?.status==='RUNNING'" class="button secondary" @click="refresh()">刷新进度</button><GenerationTaskProgress v-if="insight" :key="insight.id" :session-id="sessionId" kind="GUIDE" :reference-id="insight.id" @cancelled="refresh()" /><p v-if="insight?.errorMessage" role="alert">{{insight.errorMessage}}</p><template v-if="insight?.content"><h4>这个项目做什么</h4><p>{{insight.content.purpose}}</p><h4>有哪些模块</h4><details v-for="module in insight.content.modules" :key="module.name"><summary>{{module.name}}</summary><p>{{module.responsibility}}</p><button v-for="path in module.paths" :key="path" class="source-link" @click="emit('file',path)">查看 {{path}}</button></details><details><summary>一条业务怎样完成</summary><ol><li v-for="step in insight.content.flow" :key="step.title"><b>{{step.title}}</b><p>{{step.explanation}}</p><button v-for="path in step.paths" :key="path" class="source-link" @click="emit('file',path)">{{path}}</button></li></ol></details><details><summary>建议从哪里开始阅读</summary><ol><li v-for="step in insight.content.readingOrder" :key="step.title"><b>{{step.title}}</b><p>{{step.explanation}}</p><button v-for="path in step.paths" :key="path" class="source-link" @click="emit('file',path)">{{path}}</button></li></ol></details><details><summary>当前边界与未验证项</summary><ul><li v-for="limit in insight.content.limits" :key="limit">{{limit}}</li></ul></details></template></section></template>
<style scoped>.learning{margin-top:24px;padding-top:18px;border-top:1px solid var(--line)}h3{font-size:17px}p,li{font-size:13px;line-height:1.8;color:var(--ink-soft)}details{margin:12px 0;padding:12px;background:var(--surface-soft);border-radius:10px}summary{cursor:pointer;font-size:14px;font-weight:600}.source-link{padding:6px 10px;margin:3px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--accent);cursor:pointer}.button{margin-right:8px}</style>
